using System.Collections.Generic; using System.Data.SqlClient; using Dapper; using SchoolEnrollmentAPI.Infrastructure; using SchoolEnrollmentAPI.Models;
namespace SchoolEnrollmentAPI.Repositories { public class AlunoRepository { private readonly SqlConnectionFactory _factory = new SqlConnectionFactory(); public PagedResult<Aluno> Listar(string nome, int pagina, int tamanho) { const string sql = @"SELECT COUNT(1) FROM Aluno WHERE Ativo = 1 AND (@Nome IS NULL OR Nome LIKE '%' + @Nome + '%'); SELECT Id, Nome, Email, DataNascimento, Ativo FROM Aluno WHERE Ativo = 1 AND (@Nome IS NULL OR Nome LIKE '%' + @Nome + '%') ORDER BY Nome, Id OFFSET @Offset ROWS FETCH NEXT @Tamanho ROWS ONLY;"; using (var c = _factory.Create()) using (var multi = c.QueryMultiple(sql, new { Nome = string.IsNullOrWhiteSpace(nome) ? null : nome.Trim(), Offset = (pagina - 1) * tamanho, Tamanho = tamanho })) return new PagedResult<Aluno> { Total = multi.ReadFirst<int>(), Pagina = pagina, TamanhoPagina = tamanho, Itens = multi.Read<Aluno>().AsList() }; } public Aluno Obter(int id) { using (var c = _factory.Create()) return c.QueryFirstOrDefault<Aluno>("SELECT Id, Nome, Email, DataNascimento, Ativo FROM Aluno WHERE Id = @Id AND Ativo = 1", new { Id = id }); } public int Criar(Aluno aluno) { const string sql = "INSERT INTO Aluno (Nome, Email, DataNascimento, Ativo) VALUES (@Nome, @Email, @DataNascimento, 1); SELECT CAST(SCOPE_IDENTITY() AS INT);"; using (var c = _factory.Create()) return c.QuerySingle<int>(sql, aluno); } public bool Atualizar(int id, Aluno aluno) { const string sql = "UPDATE Aluno SET Nome=@Nome, Email=@Email, DataNascimento=@DataNascimento WHERE Id=@Id AND Ativo=1"; using (var c = _factory.Create()) return c.Execute(sql, new { Id = id, aluno.Nome, aluno.Email, aluno.DataNascimento }) == 1; } public bool Desativar(int id) { using (var c = _factory.Create()) return c.Execute("UPDATE Aluno SET Ativo=0 WHERE Id=@Id AND Ativo=1", new { Id = id }) == 1; } } }
